 const dialog=modal('装饰赠送通知单',`<form><label>文件用途<select name="mode"><option value="full">完整通知单 · 普通纸打印或下载</option><option value="overprint">预印通知单套打 · 仅填写内容</option></select></label><p class="notice" data-gift-print-notice></p><div class="formgrid"><label>纸张宽度（毫米）<input name="width" type="number" min="150" max="400" step="0.1" value="280" required></label><label>纸张高度（毫米）<input name="height" type="number" min="60" max="210" step="0.1" value="95" required></label></div><p class="fieldhelp">280 × 95 毫米仅为初始预览尺寸，照片不能确定原纸尺寸。请测量纸张宽高后填写；打印选择对应纸张、实际大小 / 100%，关闭适应纸张。</p><div class="formgrid" data-gift-offsets style="display:none"><label>向右偏移（毫米，负数向左）<input name="x" type="number" min="-20" max="20" step="0.1" value="0" required></label><label>向下偏移（毫米，负数向上）<input name="y" type="number" min="-20" max="20" step="0.1" value="0" required></label></div><div class="formerror" role="alert"></div><div class="modalfoot"><button type="button" data-gift-calibration style="display:none">下载无客户信息校准页</button><button type="button" data-gift-preview>打开打印预览</button><button type="submit" class="primary">下载 PDF</button></div></form>`,async()=>{check();await download(endpoint(),r.number+'-装饰赠送通知单-'+form.elements.mode.value+'.pdf');});
 const form=$('form',dialog),calibration=form.querySelector('[data-gift-calibration]'),preview=form.querySelector('[data-gift-preview]');
 const check=()=>{if(context!==brContext()||!dialog.open||!form.isConnected||brState.detail?.id!==r.id)throw new Error('合同、门店或账号已变化，请重新打开。');};
 const query=()=>new URLSearchParams({mode:form.elements.mode.value,paper_width_mm:form.elements.width.value,paper_height_mm:form.elements.height.value,...(form.elements.mode.value==='overprint'?{offset_x_mm:form.elements.x.value,offset_y_mm:form.elements.y.value}:{})});
 const endpoint=()=>BR_API+'/contracts/'+r.id+'/gift-document/print?'+query();
 const updateMode=()=>{const overprint=form.elements.mode.value==='overprint';form.elements.x.disabled=!overprint;form.elements.y.disabled=!overprint;form.querySelector('[data-gift-offsets]').style.display=overprint?'':'none';calibration.style.display=overprint?'':'none';form.querySelector('[data-gift-print-notice]').textContent=(overprint?'仅打印填写内容，请先下载校准页试印，再放入预印赠送通知单。':'按客户提供的四行《装饰赠送通知单》排版，可用普通纸打印。')+'日期使用合同日期，项目超过四行自动续页；金额栏保持空白，签字由经办人手签。';};
 form.elements.mode.onchange=updateMode;updateMode();
 calibration.onclick=async()=>{if(!form.reportValidity())return;calibration.disabled=true;try{check();const q=query();q.delete('mode');await download(BR_API+'/gift-print-calibration?'+q,'赠送通知单套打校准.pdf');}catch(error){$('.formerror',form).textContent=error.message;}finally{calibration.disabled=false;}};
