 if(action==='delivery-confirm'){title='财务确认交车';fields=[F('note','交车确认说明','textarea',false)];path='/delivery-confirm';notice='确认后结束合同交付部分，并抄送总经理。基础销量按对应发票上传日统计，不记录实际到账。';}
