 const current=r.effective_contract||r,form=$('form',dialog),top=document.createElement('div');top.className='br-office-fact-head';const updateFacts=preview=>{top.innerHTML=brFacts([['客户 / 车型',current.customer_name+' / '+current.model],['核算日期',prefill.period||r.delivery_state?.delivery?.accounting_on],['客户付款方式',current.terms?.submission_data?.payment_method],['库存资金性质',brCashVehicleLabel(current.terms?.submission_data?.is_cash_vehicle)],['现金车消化金额',current.terms?.submission_data?.is_cash_vehicle===true?brAmount(current.sale_price_cents):current.terms?.submission_data?.is_cash_vehicle===false?'不计现金车消化':'待核对现金车标记'],['财务核对发票金额',brAmount(r.delivery_state?.delivery?.invoice_amount_cents)],['赠品成本',preview.gift_cost_cents==null?'待补齐':brAmount(preview.gift_cost_cents)],['有偿精品销售金额',brAmount(preview.extension_data?.accessory_sales_income_cents)],['有偿精品自动成本',brAmount(preview.accessory_sales_verification?.quoted_cost_cents)],['核算采用精品成本',brAmount(preview.extension_data?.accessory_sales_cost_cents)],...(existing.note?[['原核对说明',existing.note]]:[])])+`<h3>合同冻结赠品明细</h3>`+brGiftList({gifts_snapshot:current.terms?.gifts_snapshot||[],gift_cost_total_cents:preview.gift_cost_cents});};updateFacts(computed);form.querySelector('fieldset').before(top);
